import{az as s,P as n,Q as e,aQ as t}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const y=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"构建工具/npm/npx.md","filePath":"构建工具/npm/npx.md","lastUpdated":1785343326000}'),l={name:"构建工具/npm/npx.md"};function p(o,a,c,r,d,i){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h2 id="npx-概念" tabindex="-1">npx 概念 <a class="header-anchor" href="#npx-概念" aria-label="Permalink to “npx 概念”">​</a></h2><p>npx 是 npm 5.2+ 自带的命令行工具，无需单独安装。它的核心作用是<strong>简化包的执行流程</strong>——既可以直接运行本地安装的包，也可以临时下载并执行远程包，避免了全局安装的繁琐。</p><p>原理上，npx 执行时会依次检查 <code>node_modules/.bin</code> 路径和环境变量 <code>$PATH</code>，若本地存在则直接运行；若不存在，则临时从 registry 下载到缓存目录执行，用完后清理。</p><p>参考文档：<a href="https://github.com/npm/npx" target="_blank" rel="noreferrer">npx 介绍</a></p><h2 id="核心用途" tabindex="-1">核心用途 <a class="header-anchor" href="#核心用途" aria-label="Permalink to “核心用途”">​</a></h2><h3 id="_1-执行本地安装的包" tabindex="-1">1. 执行本地安装的包 <a class="header-anchor" href="#_1-执行本地安装的包" aria-label="Permalink to “1. 执行本地安装的包”">​</a></h3><p>项目内安装的 CLI 工具位于 <code>node_modules/.bin</code>，直接调用需要写完整路径，npx 会自动解析：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 安装 webpack 到项目</span></span>
<span class="line"><span style="color:#FFCB6B;">npm</span><span style="color:#C3E88D;"> install</span><span style="color:#C3E88D;"> webpack</span><span style="color:#C3E88D;"> -D</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 传统方式：需要写完整路径</span></span>
<span class="line"><span style="color:#FFCB6B;">./node_modules/.bin/webpack</span><span style="color:#C3E88D;"> -v</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># npx 方式：自动查找本地</span></span>
<span class="line"><span style="color:#FFCB6B;">npx</span><span style="color:#C3E88D;"> webpack</span><span style="color:#C3E88D;"> -v</span></span></code></pre></div><h3 id="_2-临时安装并执行" tabindex="-1">2. 临时安装并执行 <a class="header-anchor" href="#_2-临时安装并执行" aria-label="Permalink to “2. 临时安装并执行”">​</a></h3><p>无需全局安装脚手架工具，npx 会临时下载、执行后清理：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 创建 Vite 项目，无需全局安装 create-vite</span></span>
<span class="line"><span style="color:#FFCB6B;">npx</span><span style="color:#C3E88D;"> create-vite</span><span style="color:#C3E88D;"> my-app</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 创建 React 项目</span></span>
<span class="line"><span style="color:#FFCB6B;">npx</span><span style="color:#C3E88D;"> create-react-app</span><span style="color:#C3E88D;"> my-react-app</span></span></code></pre></div><h3 id="_3-指定版本执行" tabindex="-1">3. 指定版本执行 <a class="header-anchor" href="#_3-指定版本执行" aria-label="Permalink to “3. 指定版本执行”">​</a></h3><p>可以指定特定版本的包来执行，方便版本切换：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 使用 webpack 5 打包</span></span>
<span class="line"><span style="color:#FFCB6B;">npx</span><span style="color:#C3E88D;"> webpack@5.88.0</span><span style="color:#C3E88D;"> ./src/index.js</span><span style="color:#C3E88D;"> -o</span><span style="color:#C3E88D;"> ./dist/main.js</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 使用指定版本的 Node 执行脚本（临时下载该版本 node）</span></span>
<span class="line"><span style="color:#FFCB6B;">npx</span><span style="color:#C3E88D;"> node@18</span><span style="color:#C3E88D;"> -v</span></span></code></pre></div><h2 id="npx-与-npm-run-的区别" tabindex="-1">npx 与 npm run 的区别 <a class="header-anchor" href="#npx-与-npm-run-的区别" aria-label="Permalink to “npx 与 npm run 的区别”">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>npx</th><th>npm run</th></tr></thead><tbody><tr><td>执行对象</td><td>直接执行包名</td><td>执行 scripts 中定义的别名</td></tr><tr><td>需要配置</td><td>不需要</td><td>需在 package.json 定义</td></tr><tr><td>临时安装</td><td>支持</td><td>不支持</td></tr><tr><td>指定版本</td><td>支持</td><td>不支持</td></tr><tr><td>适用场景</td><td>临时执行、一次性命令</td><td>重复使用的项目脚本</td></tr></tbody></table><p>简单来说，<code>npm run</code> 是执行 <code>package.json</code> 中预定义的脚本，而 <code>npx</code> 可以直接执行任意包。</p><h2 id="常用场景示例" tabindex="-1">常用场景示例 <a class="header-anchor" href="#常用场景示例" aria-label="Permalink to “常用场景示例”">​</a></h2><h3 id="场景一-脚手架创建项目" tabindex="-1">场景一：脚手架创建项目 <a class="header-anchor" href="#场景一-脚手架创建项目" aria-label="Permalink to “场景一：脚手架创建项目”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># Vite 脚手架</span></span>
<span class="line"><span style="color:#FFCB6B;">npx</span><span style="color:#C3E88D;"> create-vite</span><span style="color:#C3E88D;"> my-app</span><span style="color:#C3E88D;"> --template</span><span style="color:#C3E88D;"> vue</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># Next.js 脚手架</span></span>
<span class="line"><span style="color:#FFCB6B;">npx</span><span style="color:#C3E88D;"> create-next-app@latest</span><span style="color:#C3E88D;"> my-app</span></span></code></pre></div><h3 id="场景二-不同版本-webpack-切换" tabindex="-1">场景二：不同版本 webpack 切换 <a class="header-anchor" href="#场景二-不同版本-webpack-切换" aria-label="Permalink to “场景二：不同版本 webpack 切换”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 临时使用 webpack 4</span></span>
<span class="line"><span style="color:#FFCB6B;">npx</span><span style="color:#C3E88D;"> webpack@4</span><span style="color:#C3E88D;"> webpack</span><span style="color:#C3E88D;"> ./src/index.js</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 临时使用 webpack 5</span></span>
<span class="line"><span style="color:#FFCB6B;">npx</span><span style="color:#C3E88D;"> webpack@5</span><span style="color:#C3E88D;"> webpack</span><span style="color:#C3E88D;"> ./src/index.js</span></span></code></pre></div><h2 id="npx-常用参数" tabindex="-1">npx 常用参数 <a class="header-anchor" href="#npx-常用参数" aria-label="Permalink to “npx 常用参数”">​</a></h2><h3 id="no-install-强制使用本地" tabindex="-1">--no-install（强制使用本地） <a class="header-anchor" href="#no-install-强制使用本地" aria-label="Permalink to “--no-install（强制使用本地）”">​</a></h3><p>如果本地不存在该包，不会去远程下载，而是直接报错：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#FFCB6B;">npx</span><span style="color:#C3E88D;"> --no-install</span><span style="color:#C3E88D;"> webpack-dev-server</span></span></code></pre></div><h3 id="ignore-existing-p-强制使用远程" tabindex="-1">--ignore-existing / -p（强制使用远程） <a class="header-anchor" href="#ignore-existing-p-强制使用远程" aria-label="Permalink to “--ignore-existing / -p（强制使用远程）”">​</a></h3><p>忽略本地已安装的同名包，强制从远程下载最新版本执行：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># -p 是 --package 的简写，等价于 --ignore-existing</span></span>
<span class="line"><span style="color:#FFCB6B;">npx</span><span style="color:#C3E88D;"> -p</span><span style="color:#C3E88D;"> create-vite@latest</span><span style="color:#C3E88D;"> create-vite</span><span style="color:#C3E88D;"> my-app</span></span></code></pre></div><blockquote><p>注意：npm 7+ 中 <code>--ignore-existing</code> 已被废弃，推荐使用 <code>-p</code> 参数指定包名和版本。</p></blockquote><h2 id="npx-vs-npm-exec-vs-pnpm-dlx-对比" tabindex="-1">npx vs npm exec vs pnpm dlx 对比 <a class="header-anchor" href="#npx-vs-npm-exec-vs-pnpm-dlx-对比" aria-label="Permalink to “npx vs npm exec vs pnpm dlx 对比”">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>npx</th><th>npm exec</th><th>pnpm dlx</th></tr></thead><tbody><tr><td>所属工具</td><td>npm（5.2+）</td><td>npm（7+）</td><td>pnpm</td></tr><tr><td>临时安装执行</td><td>支持</td><td>支持</td><td>支持</td></tr><tr><td>多包执行</td><td>不支持</td><td>支持（多 -p）</td><td>支持</td></tr><tr><td>本地查找</td><td>支持</td><td>支持</td><td>支持</td></tr><tr><td>安装速度</td><td>正常</td><td>正常</td><td>最快</td></tr><tr><td>推荐度</td><td>通用</td><td>npm 7+ 推荐替代 npx</td><td>pnpm 用户首选</td></tr></tbody></table><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 三种方式执行 create-vite，效果等价</span></span>
<span class="line"><span style="color:#FFCB6B;">npx</span><span style="color:#C3E88D;"> create-vite</span><span style="color:#C3E88D;"> my-app</span></span>
<span class="line"><span style="color:#FFCB6B;">npm</span><span style="color:#C3E88D;"> exec</span><span style="color:#C3E88D;"> create-vite</span><span style="color:#C3E88D;"> my-app</span></span>
<span class="line"><span style="color:#FFCB6B;">pnpm</span><span style="color:#C3E88D;"> dlx</span><span style="color:#C3E88D;"> create-vite</span><span style="color:#C3E88D;"> my-app</span></span></code></pre></div><blockquote><p><code>npm exec</code> 是 npm 7+ 引入的 npx 替代方案，支持更灵活的多包执行和参数控制，是官方推荐的现代写法。</p></blockquote>`,34)])])}const x=s(l,[["render",p]]);export{y as __pageData,x as default};
